            for (j = 0; j < tier.length; j++) { p += pend[tier[j]]; }
            if (p <= 0) { continue; }
            if (s >= months) {
                for (j = 0; j < tier.length; j++) { wait[tier[j]] += pend[tier[j]] * months; }
                continue;
            }
            d = p / cap;
            if (s + d <= months) {
                integ = p * s + p * d / 2.0;
                done = p;
            } else {
                integ = p * s + p * (months - s) - cap * (months - s) * (months - s) / 2.0;
                done = cap * (months - s);
            }
            for (j = 0; j < tier.length; j++) {
                share = pend[tier[j]] / p;
                wait[tier[j]] += integ * share;
                settled[tier[j]] += done * share;
            }
            s = s + d;
        }
        return { settled: settled, wait: wait };
    }

    // Rebuilds every period from the decision history; nothing is carried forward by accumulation.
    function phases(dec, tMax) {
        var r1 = dec.round1;
        var out = [];
        var pend = { D: C.N.D, H: C.N.H, C: C.N.C };
        var t, g, r2, r3, months, method, cap, dr, settled, wait, cost, moraW, paid, nset, mult, cmp, comms, surge, denied, disputed, hid, waived, sv, cl, unsigned;
        for (t = 1; t <= tMax; t++) {
            r2 = t >= 2 ? dec.round2 : LEGACY2;
            r3 = t >= 3 ? dec.round3 : LEGACY3;
            months = C.MONTHS[t - 1];
            method = r2.settle;
            cap = C.CAP[r1.mobilize] * C.MULT[method];
            dr = drain(pend, TIERS[r1.triage], cap, months);
            settled = dr.settled;
            wait = dr.wait;
            for (g = 0; g < GROUPS.length; g++) { pend[GROUPS[g]] = Math.max(0.0, pend[GROUPS[g]] - settled[GROUPS[g]]); }
            cost = {};
            cost.ale = wait.D * C.ALE;
            cost.sec = (wait.D + wait.H) * C.SEC;
            cost.bix = wait.C * C.BIX;
            moraW = 0.0;
            if (t >= 2) {
                moraW = (wait.D * C.AVG.D + wait.H * C.AVG.H + wait.C * C.AVG.C) * C.MORA;
            }
            cost.mora = moraW;
            paid = settled.D * C.AVG.D + settled.H * C.AVG.H + settled.C * C.AVG.C;
            cost.leak = paid * (C.LEAK_ADJ[r1.mobilize] + C.LEAK_M[method]);
            nset = settled.D + settled.H + settled.C;
            cost.lae = nset * C.LAE[r1.mobilize] * C.DESK[method];
            if (t === 1) { cost.lae += C.RETAINER[r1.mobilize]; }
            mult = t === 1 ? C.COMMS_MULT1[r1.comms] : C.COMMS_MULT2[r1.comms];
            if (t >= 2) { mult = mult * pubMult(r2.public); }
            cmp = (wait.D * C.CMP.D + wait.H * C.CMP.H + wait.C * C.CMP.C) * mult;
            comms = t === 1 ? C.COMMS_COST1[r1.comms] : 0.0;
            if (t === 2) { comms += C.COMMS_COST2[r1.comms]; }
            if (t === 2 || t === 3) { comms += pubCost(r2.public); }
            if (t === 3 && r2.public === 'defensive') { comms += C.INSPECT; }
            cost.comms = comms;
            surge = 0.0;
            denied = 0.0;
            disputed = 0.0;
            if (t >= 2) {
                sv = r2.surge;
                if (sv === 'pay') {
                    if (t === 2) { surge += C.SURGE_AMT + C.SURGE_SURVEY; }
                } else if (sv === 'litigate') {
                    if (t === 2) { cmp += C.LIT_CMP; }
                    if (t === 3) { surge += C.LIT_LEGAL; }
                    if (t === 4) { surge += C.LIT_LEGAL + C.SURGE_AMT * C.LIT_SHARE * (1.0 + C.MORA * C.LIT_MORA_M); }
                    if (t === 2 || t === 3) { disputed = C.SURGE_N; }
                } else if (sv === 'deny') {
                    if (t === 2) { cmp += C.DENY_CMP; denied += C.SURGE_N; }
                    if (t === 3) { surge += C.DENY_SANCTION; }
                    disputed = C.SURGE_N;
                }
            }
            cost.surge = surge;
            hid = 0.0;
            waived = 0.0;
            if (t >= 3) {
                cl = r3.closure;
                if (cl === 'reopen') {
                    if (t === 3) { hid += C.HID_AMT + C.HID_N * C.HID_LAE; }
                } else if (cl === 'open') {
                    if (t === 3) { hid += C.OPEN_ADMIN + C.HID_N * C.OPEN_LAE; cmp += C.OPEN_CMP; }
                    if (t === 4) { hid += C.HID_AMT; }
                } else if (cl === 'waiver') {
                    unsigned = (C.HID_N - C.WAIVE_SIGNED) / C.HID_N;
                    if (t === 3) {
                        hid += C.HID_AMT * unsigned + (C.HID_N - C.WAIVE_SIGNED) * C.HID_LAE;
                        cmp += C.WAIVE_CMP;
                        denied += C.WAIVE_SIGNED;
                    }
                    if (t === 4) { hid += C.HID_AMT * (1.0 - unsigned) * C.WAIVE_LATER + C.WAIVE_FINE; }
                    waived = C.WAIVE_SIGNED;
                }
            }
            cost.hidden = hid;
            cost.friction = cmp * C.FRICTION;
            out.push({ t: t, settled: settled, wait: wait, pend: { D: pend.D, H: pend.H, C: pend.C }, cost: cost, cmp: cmp,
                denied: denied, disputed: disputed, waived: waived, paid: paid, nset: nset });
        }
        return out;
    }

    function costSum(c) {
        return c.ale + c.sec + c.bix + c.mora + c.leak + c.lae + c.comms + c.surge + c.hidden + c.friction;
    }

    function grossTrue(ph) {
        var g = C.N.D * C.AVG.D + C.N.H * C.AVG.H + C.N.C * C.AVG.C + C.BI0;
        var i, c;
        for (i = 0; i < ph.length; i++) {
            c = ph[i].cost;
            g += c.ale + c.sec + c.bix + c.leak;
        }
        return g;
    }

    function finCost(dec, ph, t) {
        var paid = ph[0].paid + ph[1].paid;
        var due = Math.max(0.0, Math.min(C.LIM, paid - C.RET));
        var rc = dec.round3.recover;
        if (t === 3) {
            if (rc === 'wait') { return due * C.FIN * C.FIN_M; }
            if (rc === 'interim') { return due * C.FIN * C.FIN_M * C.INTERIM_SHARE + C.INTERIM_ADMIN; }
            if (rc === 'inflate') { return due * C.FIN * C.FIN_M + C.INFL_LEGAL; }
        }
        if (t === 4 && rc === 'inflate') { return due * C.FIN * C.FIN_M; }
        return 0.0;
    }

    function season(dec, kTrue, totCmp, totDen) {
        var r3 = dec.round3;
        var r4 = dec.round4;
        var ex = C.EXPO[r4.exposure];
        var pr = C.PRICE[r4.price];
        var pl = C.PLAPSE[r4.price];
        var lapseS = C.LAPSE_CMP * totCmp + C.LAPSE_DENY * totDen / C.BOOK;
        var prem = 0.0, aal = 0.0, pmlw = 0.0;
        var i, z, keep, risk, mit;
        for (i = 0; i < ZONES.length; i++) {
            z = ZONES[i];
            keep = Math.max(0.0, ex[z] * (1.0 - C.LAPSE28 - pl[z] - lapseS) / (1.0 - C.LAPSE28));
            risk = Math.max(0.0, ex[z] * (1.0 - C.LAPSE28 - pl[z] * C.AS - lapseS) / (1.0 - C.LAPSE28));
            mit = (r4.price === 'risk' && z === 'coast') ? C.MIT_UPTAKE : 0.0;
            prem += C.PREM28 * C.ZSH[z] * keep * (1.0 + pr[z]) * (1.0 - mit * C.MIT_DISC);
            aal += C.AAL[z] * risk * (1.0 - mit * C.MIT_AAL);
            pmlw += C.PMLW[z] * risk * (1.0 - mit * C.MIT_PML);
        }
        var pml200 = C.PML200 * pmlw;
        var load = 1.0 + (C.LOAD[r3.reserve] || 0.0) + (C.LOAD[r3.recover] || 0.0);
        var riCost = 0.0, ceded = 0.0;
        var layers = C.LAYERS[r4.reins];
        for (i = 0; i < layers.length; i++) {
            riCost += layers[i][0] * layers[i][1] * load * pmlw;
            ceded += layers[i][2] * pmlw;
        }
        var top = C.TOPS[r4.reins];
        var rcsCat = Math.min(pml200, C.RET) + Math.max(0.0, pml200 - top);
        var rcs = C.RCS_OTHER + rcsCat;
        var shortfall = Math.max(0.0, rcs - kTrue);
        var res = prem * (1.0 - C.ATTR - C.EXP_VAR) - C.EXP_FIX - aal + ceded - riCost - C.COC * rcs - C.SHORT_COST * shortfall;
        if (r4.exposure === 'exit') { res -= C.EXIT_COST; }
        return { prem: prem, aal: aal, pml200: pml200, ri: riCost, ceded: ceded, rcs: rcs, shortfall: shortfall, res: res, ratio: kTrue / rcs };
    }

    // Full result of period t given the decisions known up to t.
    function periodResult(dec, t) {
        var ph = phases(dec, t);
        var p = ph[t - 1];
        var c = p.cost;
        var handling = costSum(c);
        var extra = 0.0;
        var r3 = t >= 3 ? dec.round3 : LEGACY3;
        var k, q;
        if (t >= 3) {
            extra += finCost(dec, ph, t);
            if (t === 3 && r3.reserve === 'top') { extra += C.TOP_CAPITAL; }
            if (t === 4 && r3.reserve === 'case') { extra += C.CASE_SANCTION; }
        }
        var costT = handling + extra;
        var g = grossTrue(ph);
        var cumOther = 0.0;
        for (k = 0; k < ph.length; k++) {
            q = ph[k].cost;
            cumOther += q.mora + q.lae + q.comms + q.surge + q.hidden + q.friction;
        }
        for (k = 3; k <= t; k++) { cumOther += finCost(dec, ph, k); }
        if (t >= 3 && r3.reserve === 'top') { cumOther += C.TOP_CAPITAL; }
        if (t >= 4 && r3.reserve === 'case') { cumOther += C.CASE_SANCTION; }
        var netTrue = C.RET + Math.max(0.0, g - C.TOP) + C.REINST + cumOther;
        var bookedG = g;
        if (t === 3 && r3.reserve === 'case') { bookedG = g * C.CASE_SHARE; }
        if (t === 3 && r3.reserve === 'top') { bookedG = g * C.TOP_SHARE; }
        var netBooked = Math.min(bookedG, C.RET) + Math.max(0.0, bookedG - C.TOP) + C.REINST + cumOther;
        var kTrue = C.K0 - netTrue;
        var ratio = (C.K0 - netBooked) / C.RCS0;
        var nv = -costT;
        var ssn = null;
        if (t === 4) {
            var totCmp = 0.0, totDen = 0.0;
            for (k = 0; k < ph.length; k++) { totCmp += ph[k].cmp; totDen += ph[k].denied; }
            ssn = season(dec, kTrue, totCmp, totDen);
            nv = ssn.res - costT;
            ratio = ssn.ratio;
        }
        var ntot = C.N.D + C.N.H + C.N.C;
        var pendAll = p.pend.D + p.pend.H + p.pend.C;
        return {
            t: t, cost: costT, nv: nv, cmp: p.cmp, closed: 1.0 - pendAll / ntot, pend: pendAll, settled: p.nset,
            homes: p.pend.D + p.pend.H + p.disputed + p.waived, denied: p.denied,
            netTrue: netTrue, netBooked: netBooked, ratio: ratio, gross: g, season: ssn, parts: c, extra: extra
        };
    }

    class CatastrofeCostaAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Catástrofe en la Costa';
            this.version = '1.0.0';
            this.ROUNDS = [
                { panel: 'roundPanel1', nameKey: 'r1_name', briefKey: 'r1_brief' },
                { panel: 'roundPanel2', nameKey: 'r2_name', briefKey: 'r2_brief' },
                { panel: 'roundPanel3', nameKey: 'r3_name', briefKey: 'r3_brief' },
                { panel: 'roundPanel4', nameKey: 'r4_name', briefKey: 'r4_brief' }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    rounds: [],
                    periods: [],
                    deniedCum: 0,
                    capFlag: false,
                    dec: {},
                    scoreHistory: [],
                    performance: { overallScore: 0 },
                    performanceTier: 'beginner'
