        }

        _periodHtml(ds, q) {
            var pc = q.parts;
            var v = {
                closed: this._fmtPct(q.closed), settled: this._fmtNum(q.settled, 0), pend: this._fmtNum(q.pend, 0),
                homes: this._fmtNum(q.homes, 0), cmp: this._fmtNum(q.cmp, 0),
                ale: this._fmtM(pc.ale), sec: this._fmtM(pc.sec), bix: this._fmtM(pc.bix), mora: this._fmtM(pc.mora),
                leak: this._fmtM(pc.leak), lae: this._fmtM(pc.lae), comms: this._fmtM(pc.comms), surge: this._fmtM(pc.surge),
                hid: this._fmtM(pc.hidden), fr: this._fmtM(pc.friction), extra: this._fmtM(q.extra),
                nv: this._fmtM(q.nv), net: this._fmtM(q.netTrue), ratio: this._fmtPct(q.ratio)
            };
            var html = this._t('sem_body', v);
            html += '<span class="ea2166-cases">' + this._t('s_costs', v) + '</span>';
            html += '<span class="ea2166-cases">' + this._t('s_net', v) + '</span>';
            if (q.season) {
                var sn = q.season;
                html += '<span class="ea2166-reveal">' + this._t('s_season', {
                    prem: this._fmtM(sn.prem), aal: this._fmtM(sn.aal), ri: this._fmtM(sn.ri), pml: this._fmtM(sn.pml200),
                    rcs: this._fmtM(sn.rcs), res: this._fmtM(sn.res)
                }) + '</span>';
                if (sn.shortfall > 0) { html += '<span class="ea2166-reveal">' + this._t('s_short', { sh: this._fmtM(sn.shortfall) }) + '</span>'; }
                if (q.exit) { html += '<span class="ea2166-reveal">' + this._t('s_exit') + '</span>'; }
            }
            if (q.denied > 0) { html += '<span class="ea2166-reveal">' + this._t('s_denied', { d: this._fmtNum(q.denied, 0) }) + '</span>'; }
            var keys = ds.capKeys || [];
            var i;
            for (i = 0; i < keys.length; i++) { html += '<span class="ea2166-reveal">' + this._t(keys[i]) + '</span>'; }
            return html;
        }

        _feedbackHtml(ds, r) {
            var v = { pts: this._fmtNum(Math.round(r.pts * 10) / 10, 1) };
            return '<strong>' + this._t('fb_points', v) + '</strong> ' + this._t('fb_r' + r.period + '_' + r.verdictKey, v);
        }

        _readSelect(id, allowed) {
            var el = document.getElementById(id);
            if (!el) { return null; }
            var val = String(el.value);
            if (allowed.indexOf(val) === -1) { return null; }
            return val;
        }

        validateDecisions(decisions) {
            var sim = window.mySimulation;
            var state = sim && sim.state ? sim.state : { currentPeriod: 1, history: [] };
            var period = state.currentPeriod || 1;
            var done = state.history ? state.history.length : 0;
            var warn = function(key) {
                sim.uiManager.showNotification(sim.t(key), 'warning');
                return false;
            };
            if (done >= this.ROUNDS.length || period > this.ROUNDS.length) { return warn('warn_finished'); }
            if (period === 1) {
                var mobilize = this._readSelect('r1_mobilize', CTRL.round1.mobilize);
                var triage = this._readSelect('r1_triage', CTRL.round1.triage);
                var comms = this._readSelect('r1_comms', CTRL.round1.comms);
                if (!mobilize || !triage || !comms) { return warn('warn_r1'); }
                decisions.round1 = { mobilize: mobilize, triage: triage, comms: comms };
                return true;
            }
            if (period === 2) {
                var settle = this._readSelect('r2_settle', CTRL.round2.settle);
                var surge = this._readSelect('r2_surge', CTRL.round2.surge);
                var pub = this._readSelect('r2_public', CTRL.round2.public);
                if (!settle || !surge || !pub) { return warn('warn_r2'); }
                decisions.round2 = { settle: settle, surge: surge, public: pub };
                return true;
            }
            if (period === 3) {
                var reserve = this._readSelect('r3_reserve', CTRL.round3.reserve);
                var recover = this._readSelect('r3_recover', CTRL.round3.recover);
                var closure = this._readSelect('r3_closure', CTRL.round3.closure);
                if (!reserve || !recover || !closure) { return warn('warn_r3'); }
                decisions.round3 = { reserve: reserve, recover: recover, closure: closure };
                return true;
            }
            if (period === 4) {
                var exposure = this._readSelect('r4_exposure', CTRL.round4.exposure);
                var price = this._readSelect('r4_price', CTRL.round4.price);
                var reins = this._readSelect('r4_reins', CTRL.round4.reins);
                if (!exposure || !price || !reins) { return warn('warn_r4'); }
                decisions.round4 = { exposure: exposure, price: price, reins: reins };
                return true;
            }
            return warn('warn_finished');
        }

        calculateResults(state) {
            var out = this._computeRound(state);
            var self = this;
            setTimeout(function() { self._updateBriefing(window.mySimulation.state); }, 400);
            return out;
        }

        // Round model. Pending claims, the net cost of Tadeo and the capital are rebuilt from the decision history, so a resubmit is idempotent.
        _computeRound(state) {
            var ds = state.domainState;
            var raw = state.decisions || {};
            var period = state.currentPeriod || 1;
            var saved = ds.dec || {};
            var d = {};
            var k;
            for (k = 1; k <= period; k++) {
                if (raw['round' + k]) { d['round' + k] = raw['round' + k]; }
                else if (k < period && saved['round' + k]) { d['round' + k] = saved['round' + k]; }
            }
            ds.dec = JSON.parse(JSON.stringify(d));
            var rounds = [];
            var periods = [];
            var total = 0.0;
            var dcum = 0.0;
            var flag = false;
            var cap = 100.0;
            var solvKey = false;
            var r, known, q, rub, outp, pts;
            for (r = 1; r <= period; r++) {
                known = this._known(d, r);
                q = periodResult(known, r);
                dcum += q.denied;
                if (r >= 2 && known.round2.surge === 'deny') { flag = true; }
                if (r >= 3 && known.round3.closure === 'waiver') { flag = true; }
                rub = this._rubric(known, r);
                outp = 10.0 * clamp((q.nv - C.NV_LO[r - 1]) / (C.NV_HI[r - 1] - C.NV_LO[r - 1]), 0.0, 1.0);
                pts = rub + outp;
                total += pts;
                cap = flag ? Math.max(C.CAP_FLOOR, C.CAP_BASE - C.CAP_W * dcum) : 100.0;
                solvKey = false;
                if (r === 4 && q.season.shortfall > 0) {
                    var sc = Math.max(C.CAP_FLOOR, C.SOLV_BASE - C.SOLV_W * q.season.shortfall);
                    if (sc < cap) { solvKey = true; }
                    cap = Math.min(cap, sc);
                }
                if (r === 4) { q.exit = known.round4.exposure === 'exit'; }
                periods.push(q);
                rounds.push({ period: r, rub: rub, outp: outp, pts: pts, verdictKey: this._verdict(known, r) });
            }
            ds.rounds = rounds;
            ds.periods = periods;
            ds.deniedCum = dcum;
            ds.capFlag = flag;
            ds.total = total;
            ds.cap = cap;
            var score = this._composite(ds);
            ds.capKeys = [];
            if (cap < 100 && total > cap) { ds.capKeys.push(solvKey ? 'cap_solv' : 'cap_deny'); }
            ds.performance = { overallScore: score };
            ds.performanceTier = this._tier(score);
            ds.scoreHistory = (ds.scoreHistory || []).slice(0, period - 1);
            ds.scoreHistory[period - 1] = score;
            ds.scoreHistory.length = period;
            var last = periods[periods.length - 1];
            return {
                period: period,
                roundPoints: Math.round(rounds[period - 1].pts * 10) / 10,
                closed: Math.round(last.closed * 1000) / 10,
                homes: Math.round(last.homes),
                cmp: Math.round(last.cmp),
                nv: Math.round(last.nv * 10) / 10,
                ratio: Math.round(last.ratio * 1000) / 10,
                score: score,
                overallScore: score
            };
        }

        _known(d, r) {
            var out = {};
            var k;
            for (k = 1; k <= r; k++) { if (d['round' + k]) { out['round' + k] = d['round' + k]; } }
            return out;
        }

        _rubric(dec, r) {
            var P = C.PTS;
            var d;
            if (r === 1) {
                d = dec.round1;
                return P.mob1[d.mobilize] + P.tri1[d.triage] + P.com1[d.comms];
            }
            if (r === 2) {
                d = dec.round2;
                return P.set2[d.settle] + P.sur2[d.surge] + P.pub2[d.public];
            }
            if (r === 3) {
                d = dec.round3;
                return P.res3[d.reserve] + P.rec3[d.recover] + P.clo3[d.closure];
            }
            d = dec.round4;
            return P.exp4[d.exposure] + P.pri4[d.price] + P.rei4[d.reins];
        }

        _verdict(dec, r) {
            var d;
            if (r === 1) {
                d = dec.round1;
                if (d.comms === 'promise') { return 'promise'; }
                if (d.mobilize === 'own') { return 'own'; }
                if (d.comms === 'silence') { return 'silence'; }
                if (d.triage === 'commercial') { return 'commercial'; }
                if (d.triage === 'fifo') { return 'fifo'; }
                if (d.mobilize === 'spot') { return 'spot'; }
                return 'ok';
            }
            if (r === 2) {
                d = dec.round2;
                if (d.surge === 'deny') { return 'deny'; }
                if (d.settle === 'noverify') { return 'noverify'; }
                if (d.surge === 'litigate') { return 'litigate'; }
                if (d.settle === 'full') { return 'full'; }
                if (d.public === 'viral') { return 'viral'; }
                if (d.public === 'defensive') { return 'defensive'; }
                return 'ok';
            }
            if (r === 3) {
                d = dec.round3;
                if (d.closure === 'waiver') { return 'waiver'; }
                if (d.reserve === 'case') { return 'case'; }
                if (d.recover === 'inflate') { return 'inflate'; }
                if (d.reserve === 'top') { return 'top'; }
                if (d.recover === 'wait') { return 'wait'; }
                if (d.closure === 'open') { return 'open'; }
                return 'ok';
            }
            d = dec.round4;
            if (d.reins === 'same') { return 'same'; }
            if (d.exposure === 'exit') { return 'exit'; }
            if (d.exposure === 'keep') { return 'keep'; }
            if (d.price === 'flat') { return 'flat'; }
            if (d.price === 'coast40') { return 'coast40'; }
            if (d.reins === 'to500') { return 'to500'; }
            return 'ok';
        }

        _composite(ds) {
            var total = Math.min((ds && typeof ds.cap === 'number') ? ds.cap : 100, (ds && ds.total) || 0);
            return Math.max(0, Math.min(100, Math.round(total)));
        }

        _tier(score) {
            if (score >= 75) { return 'excellent'; }
            if (score >= 55) { return 'good'; }
            return 'beginner';
        }

