        getHint(state, results) {
            var ds = state.domainState || {};
            var r = (ds.rounds || [])[(results.period || 1) - 1];
            if (!r) { return null; }
            return this._t('hint_r' + r.period + '_' + r.verdictKey);
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) { return {}; }
            var ds = window.mySimulation.state.domainState;
            var ps = ds.periods || [];
            var score = this._composite(ds);
            var performance = 'Beginner';
            if (score >= 55) { performance = 'Good'; }
            if (score >= 75) { performance = 'Excellent'; }
            var cmp = 0.0;
            var i;
            for (i = 0; i < ps.length; i++) { cmp += ps[i].cmp; }
            var last = ps.length ? ps[ps.length - 1] : null;
            var net = last ? last.netTrue : 0;
            var ratio = last ? last.ratio : 0;
            var insights = [];
            insights.push(net < 2600 ? this._t('insight_net_ok') : this._t('insight_net_bad'));
            insights.push((ds.deniedCum || 0) > 0 ? this._t('insight_deny_bad') : this._t('insight_deny_ok'));
            insights.push(cmp < 3000 ? this._t('insight_cmp_ok') : this._t('insight_cmp_bad'));
            insights.push(ratio >= 1.0 ? this._t('insight_solv_ok') : this._t('insight_solv_bad'));
            insights.push(this._t('insight_next'));
            return {
                composite: score,
                overallScore: score,
                totalScore: score,
                score: score,
                net: net,
                cmp: cmp,
                ratio: ratio,
                denied: ds.deniedCum || 0,
                rounds: (ds.scoreHistory || []).length,
                performance: performance,
                performanceKey: performance.toLowerCase(),
                performanceLabel: this._cl('grade_' + performance.toLowerCase(), performance),
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
